function rnd(x){var r=PR().round;if(r==='90')return x<=9.9?9.9:+(Math.ceil((x-9.9)/10)*10+9.9).toFixed(2);if(r==='99')return+(Math.ceil(x)-.01).toFixed(2);return+x.toFixed(2)}
function sugg(p,m){var mg=N(p.margin)||N(PR().margin),d=1-vpct(m||'c3')-mg/100;return d>0?rnd(ctot(p)/d):0}
function minp(p,m){var d=1-vpct(m);return d>0?+(ctot(p)/d).toFixed(2):0}
function prof(p,x,m){return x*(1-vpct(m))-ctot(p)}
