function bkInfo(){var d=DB.lastBackup,days=d?Math.floor((Date.now()-d)/864e5):null;if(d&&days<7)return'<div class="mu" style="margin-bottom:8px">Último backup: '+new Date(d).toLocaleDateString('pt-BR')+'</div>';return'<div class="tg" onclick="go(\'settings\')" style="display:block;padding:12px;margin-bottom:12px;border-radius:12px;cursor:pointer">⚠ '+(d?'Último backup há '+days+' dias.':'Você ainda não fez backup.')+' Toque aqui para fazer o backup.</div>'}
async function backup(){DB.lastBackup=Date.now();save();var j=JSON.stringify(DB),n='maria-flor-backup-'+today()+'.json',f=null;
 try{f=new File([j],n,{type:'application/json'})}catch(e){}
 if(f&&navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:'Backup Maria Flor'});render();return}catch(e){if(e&&e.name==='AbortError')return}}
 var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([j],{type:'application/json'}));a.download=n;document.body.appendChild(a);a.click();a.remove();render()}
function restore(el){var f=el.files[0];if(!f)return;var r=new FileReader();r.onload=function(){try{var d=JSON.parse(r.result);if(!d.products||!d.sales)throw 0;if(!confirm('Substituir TODOS os dados atuais pelo backup?')){el.value='';return}DB=d;['products','sales','moves','cash','bills','clients','discounts','categories','cfg','prc'].forEach(function(k){DB[k]=DB[k]||[]});save();render()}catch(e){alert('Arquivo de backup inválido.')}el.value=''};r.readAsText(f)}
